<script setup lang="ts">import {reactive,watch} from 'vue';type Field={key:string;label:string;type?:'textarea'|'date'|'number'|'select';options?:string[]};const props=defineProps<{modelValue?:Record<string,unknown>|null;fields:Field[]}>();const emit=defineEmits<{save:[value:Record<string,unknown>];cancel:[]}>();const form=reactive<Record<string,unknown>>({});watch(()=>props.modelValue,v=>{for(const f of props.fields)form[f.key]=v?.[f.key]??''},{immediate:true,deep:true});</script>
<template><form class="work-item-form" @submit.prevent="emit('save',{...form})"><label v-for="field in fields" :key="field.key">{{field.label}}<select v-if="field.type==='select'" v-model="form[field.key] as string"><option value="" disabled>请选择{{field.label}}</option><option v-for="option in field.options||[]" :key="option">{{option}}</option></select><textarea v-else-if="field.type==='textarea'" v-model="form[field.key] as string" rows="3" :placeholder="`请输入${field.label}`"/><input v-else v-model="form[field.key] as string" :type="field.type||'text'" :placeholder="`请输入${field.label}`"/></label><div class="form-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button class="primary">保存</button></div></form></template>